import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import {
	OperationalCostCategory,
	OperationalCostPaymentStatus,
	OperationalCostRecurrency,
	type CurrencyCode,
} from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'
import type { FinanceDomainErrors } from '../errors'

export const PaymentStatusEntrySchema = z.object({
	occurrenceDate: z.date(),
	status: z.enum(OperationalCostPaymentStatus),
})

export const OperationalCostSchema = z.object({
	storeId: z.instance(Id),
	category: z.enum(OperationalCostCategory),
	description: z.string().min(1).max(500),
	amount: z.instance(MonetaryAmount).refine(m => m.amountCents > 0, {
		error: 'INVALID_AMOUNT' as FinanceDomainErrors,
	}),
	recurrency: z.enum(OperationalCostRecurrency),
	startDate: z.date(),
	endDate: z.date().nullable(),
	statusEntries: z.array(PaymentStatusEntrySchema).default([]),
	deletedAt: z.date().nullable(),
})

export type OperationalCostProps = Z.infer<typeof OperationalCostSchema>

/**
 * `OperationalCost` aggregate per spec § BC8 Finance. Recurrent or
 * one-off business expense (rent, employee salary, software, etc).
 * `statusEntries[]` tracks per-occurrence payment status — one entry
 * per occurrenceDate; toggling re-stamps the entry for that date.
 *
 * Soft-deleted by `delete()`: row preserved so historical analytics
 * keep their context.
 */
export class OperationalCost extends AggregateRoot<typeof OperationalCostSchema> {
	static override schema = OperationalCostSchema

	static create(data: {
		storeId: string
		category: OperationalCostCategory
		description: string
		amount: { amountCents: number; currency: CurrencyCode }
		recurrency: OperationalCostRecurrency
		startDate: Date
		endDate?: Date
	}): OperationalCost {
		if (data.endDate !== undefined && data.startDate > data.endDate) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'startDate must be <= endDate')
		}
		return new OperationalCost({
			storeId: data.storeId,
			category: data.category,
			description: data.description,
			amount: data.amount,
			recurrency: data.recurrency,
			startDate: data.startDate,
			endDate: data.endDate ?? null,
			statusEntries: [],
			deletedAt: null,
		})
	}

	update(patch: {
		category?: OperationalCostCategory
		description?: string
		amount?: { amountCents: number; currency: CurrencyCode }
		recurrency?: OperationalCostRecurrency
		startDate?: Date
		endDate?: Date | null
	}): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'cannot update a deleted OperationalCost')
		}
		const effectiveStart = patch.startDate ?? this.startDate
		const effectiveEnd = patch.endDate !== undefined ? patch.endDate : this.endDate
		if (effectiveEnd !== null && effectiveStart > effectiveEnd) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'startDate must be <= endDate')
		}
		if (patch.category !== undefined) {
			this.category = patch.category
		}
		if (patch.description !== undefined) {
			this.description = patch.description
		}
		if (patch.amount !== undefined) {
			this.amount = new MonetaryAmount(patch.amount)
		}
		if (patch.recurrency !== undefined) {
			this.recurrency = patch.recurrency
		}
		if (patch.startDate !== undefined) {
			this.startDate = patch.startDate
		}
		if (patch.endDate !== undefined) {
			this.endDate = patch.endDate
		}
		this.validate()
	}

	setStatus(occurrenceDate: Date, status: OperationalCostPaymentStatus): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'cannot toggle status on a deleted OperationalCost')
		}
		const i = this.statusEntries.findIndex(e => e.occurrenceDate.getTime() === occurrenceDate.getTime())
		if (i >= 0) this.statusEntries[i] = { occurrenceDate, status }
		else this.statusEntries.push({ occurrenceDate, status })
		this.validate()
	}

	delete(): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'OperationalCost already deleted')
		}
		this.deletedAt = new Date()
		this.validate()
	}

	get isDeleted(): boolean {
		return this.deletedAt !== null
	}
}

export interface OperationalCost extends OperationalCostProps {}

import { pgSchema, uuid, text, timestamp, integer, bigint, jsonb, doublePrecision, index } from 'drizzle-orm/pg-core'

/**
 * `finance` is BK Dash's BC8 Finance schema.
 *
 * All TS-owned merchant aggregates — no Go writes here. The Go-side
 * sync engine emits provider-reported amounts (gateway fees inline in
 * OrderTransaction, etc.); Finance owns the merchant-side
 * configuration that turns those amounts into profit margins.
 *
 * Tables:
 *   - `taxes`               — Store-scoped, time-effective tax regime
 *   - `fees_configuration`  — Store-scoped header + typed sub-fee
 *                             jsonb arrays (gateway / checkout / shipping)
 *   - `operational_costs`   — merchant cost ledger w/ status entries
 *   - `warranty_reserves`   — % of revenue reserved per Store (time-effective)
 *   - `fx_rates`            — append-only, query by (from, to, startDate ≤ at)
 */
export const financeSchema = pgSchema('finance')

/**
 * `taxes` — one row per (storeId, startDate slice). `endDate` nullable
 * means "still effective". Queries pick the row matching
 * `startDate <= date AND (endDate IS NULL OR endDate > date)`.
 */
export const taxes = financeSchema.table(
	'taxes',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// TaxType enum (NONE | PRESUMED_PROFIT | REAL_PROFIT).
		type: text('type').notNull(),
		// TaxDeductionType enum (NONE | PRODUCT_COST | PRODUCT_COST_AND_MARKETING).
		deductionType: text('deduction_type').notNull(),

		// Effective tax rate as a fraction 0..1 (e.g. 0.085 = 8.5%). Stored
		// as double precision because tax calculations vary in precision
		// per jurisdiction and a fixed-point representation would force
		// us to pick a unit per market.
		rate: doublePrecision('rate').notNull(),

		// Spec §4 BC8 `Taxes` aggregate: per-Store profit multiplier
		// applied to revenue tax (e.g. 1.0 = neutral, 1.15 = 15% safety
		// buffer). Stored alongside `rate` to keep T25 reads to a single
		// SELECT. Default 1.0 = no multiplier so historical rows backfill
		// to a neutral value.
		revenueTaxMultiplier: doublePrecision('revenue_tax_multiplier').notNull().default(1.0),

		// Spec §4 BC8 + T25: per-platform marketing-tax overrides keyed by
		// MarketingPlatform (META | GOOGLE_ADS | TIKTOK). Empty map = no
		// per-platform overrides — fall back to `rate`. JSONB shape is
		// `Partial<Record<MarketingPlatform, number>>` per spec line 836.
		marketingTaxRatePerPlatform: jsonb('marketing_tax_rate_per_platform').notNull().default({}),

		startDate: timestamp('start_date', { withTimezone: true }).notNull(),
		endDate: timestamp('end_date', { withTimezone: true }),

		// Audit pointer to the user who applied the most recent change.
		// Nullable (no FK) — preserves audit trail when a user is removed.
		updatedByUserId: text('updated_by_user_id'),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeIdx: index('taxes_store_id_idx').on(t.storeId),
		// Time-effective lookup index.
		storeStartDateIdx: index('taxes_store_start_date_idx').on(t.storeId, t.startDate),
	}),
)

/**
 * `fees_configuration` — single header row per Store with three typed
 * jsonb arrays of sub-fees:
 *
 *   - gateway_fees: GatewayFee[]
 *       { platform: PaymentGateway, paymentMethod: PaymentMethod,
 *         percentage: number, fixed: { amountCents, currency }[] }
 *   - checkout_fees: CheckoutFee[]
 *       { platform: CheckoutPlatform, rate: number }
 *   - shipping_fees: ShippingFee[]
 *       { type: ShippingCostType, value: ShippingCostValue }
 *
 * jsonb chosen over separate child tables because (a) read shape is
 * always "the full configuration for one Store", and (b) the
 * per-platform sub-shapes vary (e.g. ShippingCostValue is a 4-variant
 * discriminated union from spec — modeling it relationally would
 * require multiple child tables for a write that happens N×/year.)
 */
export const feesConfiguration = financeSchema.table(
	'fees_configuration',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		gatewayFees: jsonb('gateway_fees').notNull(),
		checkoutFees: jsonb('checkout_fees').notNull(),
		// Singular: the spec's FeesConfiguration carries one shipping
		// fee per row (matches the entity's `shippingFee` field).
		// Stored as a nullable jsonb so the "no shipping fee
		// configured yet" state encodes as JSON null.
		shippingFee: jsonb('shipping_fee'),

		// Spec §4 BC8 + C40: time-effective semantics matching `taxes`.
		// Multiple rows per Store; the active one has `endDate IS NULL`.
		// C40 closes the previous row's endDate and inserts a new one.
		// Default startDate = row insertion time (safe for historical
		// single-row data migrated forward — it becomes the first slice).
		startDate: timestamp('start_date', { withTimezone: true }).notNull().defaultNow(),
		endDate: timestamp('end_date', { withTimezone: true }),

		// Audit pointer (same rationale as `taxes.updatedByUserId`).
		updatedByUserId: text('updated_by_user_id'),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// Time-effective lookup: (storeId, startDate) replaces the previous
		// `(storeId) UNIQUE` constraint. Active-row lookup uses
		// `WHERE storeId = ? AND endDate IS NULL`.
		storeStartDateIdx: index('fees_configuration_store_start_date_idx').on(t.storeId, t.startDate),
	}),
)

/**
 * `operational_costs` — merchant cost ledger. Each row is one cost
 * line item with its own recurrence pattern. `status_entries` is a
 * jsonb array of OperationalCostStatusEntry ({ date, status }) — one
 * entry per occurrence, toggled by the merchant
 * (e.g. mark October's RENT row as PAID).
 */
export const operationalCosts = financeSchema.table(
	'operational_costs',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// Free-form merchant description ("November salary advance",
		// "Adobe CC", …). category is the enum classification.
		description: text('description').notNull(),
		category: text('category').notNull(),

		// OperationalCostRecurrency enum (ONCE | DAILY | WEEKLY | … |
		// YEARLY | NONE).
		recurrency: text('recurrency').notNull(),

		amountCents: bigint('amount_cents', { mode: 'bigint' }).notNull(),
		currency: text('currency').notNull(),

		// First occurrence date. For recurring costs the date implies
		// each future occurrence (e.g. MONTHLY starting Jan 15 →
		// Feb 15, Mar 15, …).
		startDate: timestamp('start_date', { withTimezone: true }).notNull(),
		// Optional terminator for recurring costs ("stop billing this
		// after X"); nullable = still recurring.
		endDate: timestamp('end_date', { withTimezone: true }),

		// jsonb array of { occurrenceDate, status } per occurrence —
		// matches the OperationalCost entity's statusEntries shape
		// verbatim. Status uses OperationalCostPaymentStatus
		// (PAID | UNPAID | OVERDUE | CANCELLED).
		statusEntries: jsonb('status_entries').notNull(),

		// Soft-delete timestamp. T27 ListOperationalCosts filters out
		// rows where this is non-null — the entity uses `deletedAt`
		// alone as the "is this row visible?" signal (no separate
		// `active` flag).
		deletedAt: timestamp('deleted_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeIdx: index('operational_costs_store_id_idx').on(t.storeId),
		categoryIdx: index('operational_costs_category_idx').on(t.category),
		// Date scans for analytics rollups.
		startDateIdx: index('operational_costs_start_date_idx').on(t.startDate),
	}),
)

/**
 * `warranty_reserves` — per-Store percentage of revenue reserved for
 * warranty claims. Time-effective (multiple rows per Store; queries
 * pick the row whose start_date ≤ now AND (end_date IS NULL OR
 * end_date > now)).
 */
export const warrantyReserves = financeSchema.table(
	'warranty_reserves',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// Fraction 0..1 of revenue to reserve. Same precision rationale as
		// `taxes.rate`.
		rate: doublePrecision('rate').notNull(),

		// Spec § BC8 BC and the WarrantyReserve entity name the
		// time-effective window `effectiveFrom`/`effectiveTo` to
		// distinguish it from the soft-delete `deletedAt` timestamp.
		// (Taxes uses `start_date`/`end_date` because it has no soft
		// delete; reusing the same names here would conflate the two
		// audit dimensions.)
		effectiveFrom: timestamp('effective_from', { withTimezone: true }).notNull(),
		effectiveTo: timestamp('effective_to', { withTimezone: true }),
		// Soft-delete timestamp. listByStoreId filters out rows where
		// this is non-null; the supersession path uses effectiveTo
		// (not deletedAt) so historical analytics keep the row
		// visible.
		deletedAt: timestamp('deleted_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeEffectiveFromIdx: index('warranty_reserves_store_effective_from_idx').on(t.storeId, t.effectiveFrom),
	}),
)

/**
 * `fx_rates` — append-only currency conversion source of truth.
 *
 * Hourly CaptureFxRates cron emits rows from CURRENCY_API; merchants
 * may insert MANUAL overrides; providers may report rates inline
 * (PROVIDER_REPORTED, captured during transaction ingest).
 *
 * Queried with the canonical pattern:
 *   SELECT * FROM fx_rates
 *    WHERE from_currency = ? AND to_currency = ?
 *      AND start_date <= ?
 *    ORDER BY start_date DESC LIMIT 1
 *
 * The composite index on (from_currency, to_currency, start_date DESC)
 * makes that query a single-page seek.
 */
export const fxRates = financeSchema.table(
	'fx_rates',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		fromCurrency: text('from_currency').notNull(),
		toCurrency: text('to_currency').notNull(),

		// Conversion rate: 1 unit of fromCurrency = `rate` units of
		// toCurrency. Stored as `text` to preserve provider-side
		// decimal precision verbatim (e.g. '5.10' stays '5.10', not
		// coerced to 5.1). Queries never sort or aggregate on rate
		// (ORDER BY runs on start_date) so the lack of numeric
		// semantics is fine. The FxRate entity carries `rate: string`
		// matching this column.
		rate: text('rate').notNull(),

		// FxRateSource enum (CURRENCY_API | MANUAL | PROVIDER_REPORTED).
		source: text('source').notNull(),

		// When this rate became effective. Multiple rows may exist for
		// the same currency pair; queries pick the most recent ≤ desired
		// timestamp.
		startDate: timestamp('start_date', { withTimezone: true }).notNull(),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
	},
	t => ({
		// Canonical query index — covers the "find rate at time T" path.
		pairStartDateIdx: index('fx_rates_pair_start_date_idx').on(t.fromCurrency, t.toCurrency, t.startDate),
		sourceIdx: index('fx_rates_source_idx').on(t.source),
	}),
)

// AUTO-GENERATED by packages/contracts/codegen/emit-wire-ts.ts — do not edit.
/** Cadence at which an OperationalCost recurs. ONCE = single occurrence (different from NONE which means "no recurrence semantics applicable"). */
export enum OperationalCostRecurrency {
	ONCE = 'ONCE',
	DAILY = 'DAILY',
	WEEKLY = 'WEEKLY',
	MONTHLY = 'MONTHLY',
	BIMESTER = 'BIMESTER',
	TRIMESTER = 'TRIMESTER',
	SEMESTER = 'SEMESTER',
	YEARLY = 'YEARLY',
	NONE = 'NONE',
}

import { Repository } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { OperationalCost } from '../../entities/OperationalCost'

export interface OperationalCostListQuery {
	storeId: string
	page: number
	limit: number
}

export interface OperationalCostListResult {
	total: number
	items: OperationalCost[]
}

export abstract class OperationalCostRepository extends Repository<OperationalCost> {
	abstract findById(id: string, tx?: Transaction): Promise<OperationalCost | undefined>
	abstract list(query: OperationalCostListQuery, tx?: Transaction): Promise<OperationalCostListResult>
}

import { injectable } from 'tsyringe-neo'
import { and, count, desc, eq, isNull, sql } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { operationalCosts } from '@bk-dash/contracts/db'
import { OperationalCostPaymentStatus } from '@bk-dash/contracts-typescript/wire/enums'
import { OperationalCost, OperationalCostSchema } from '../../entities/OperationalCost'
import { OperationalCostRepository, type OperationalCostListQuery, type OperationalCostListResult } from './OperationalCostRepository'

/**
 * Drizzle-backed OperationalCostRepository (iter 306 — paired with
 * the 0023 schema rename label→description + drop of payment_method
 * and active columns, bringing the table into agreement with the
 * entity contract).
 *
 * `list` filters out soft-deleted rows (`deletedAt IS NULL`) and
 * paginates newest-first by createdAt. The entity's `deletedAt` is
 * the canonical "is this row visible?" signal — there's no separate
 * `active` flag the spec aspired to but the aggregate never grew up
 * to need.
 *
 * `amountCents` round-trips via `Number()` / `BigInt()` because the
 * column is `bigint` (storage) while the entity carries `number`
 * (cents within JS safe-int range).
 */
@injectable()
export class DrizzleOperationalCostRepository extends OperationalCostRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<OperationalCost | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(operationalCosts).where(eq(operationalCosts.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async list(query: OperationalCostListQuery, tx?: DrizzleClient): Promise<OperationalCostListResult> {
		const dbc = tx ?? this.db
		const where = and(eq(operationalCosts.storeId, query.storeId), isNull(operationalCosts.deletedAt))
		const result = await tryCatchAsync(async () => {
			const offset = Math.max(0, (query.page - 1) * query.limit)
			const [items, totalRows] = await Promise.all([
				dbc.select().from(operationalCosts).where(where).orderBy(desc(operationalCosts.createdAt)).limit(query.limit).offset(offset),
				dbc
					.select({ value: count() })
					.from(operationalCosts)
					.where(where ?? sql`true`),
			])
			return { items, total: Number(totalRows[0]?.value ?? 0) }
		})
		if (!result.success) throw result.error
		return {
			total: result.data.total,
			items: result.data.items.map(r => this.toDomain(r)),
		}
	}

	async save(entity: OperationalCost, tx?: DrizzleClient): Promise<OperationalCost> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(operationalCosts)
				.values(data)
				.onConflictDoUpdate({
					target: operationalCosts.id,
					set: {
						storeId: data.storeId,
						description: data.description,
						category: data.category,
						recurrency: data.recurrency,
						amountCents: data.amountCents,
						currency: data.currency,
						startDate: data.startDate,
						endDate: data.endDate,
						statusEntries: data.statusEntries,
						deletedAt: data.deletedAt,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(operationalCosts).where(eq(operationalCosts.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof operationalCosts.$inferSelect): OperationalCost {
		const parsed = OperationalCostSchema.parse({
			storeId: row.storeId,
			description: row.description,
			category: row.category,
			recurrency: row.recurrency,
			amount: { amountCents: Number(row.amountCents), currency: row.currency },
			startDate: row.startDate,
			endDate: row.endDate,
			// statusEntries is JSONB: occurrenceDate round-trips as an ISO string, so
			// coerce it back to a Date before the entity schema (z.date()) parses it.
			statusEntries: ((row.statusEntries ?? []) as Array<{ occurrenceDate: string; status: OperationalCostPaymentStatus }>).map(e => ({
				occurrenceDate: new Date(e.occurrenceDate),
				status: e.status,
			})),
			deletedAt: row.deletedAt,
		})
		return new OperationalCost({
			...parsed,
			id: row.id,
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: OperationalCost): typeof operationalCosts.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			description: entity.description,
			category: entity.category,
			recurrency: entity.recurrency,
			amountCents: BigInt(entity.amount.amountCents),
			currency: entity.amount.currency,
			startDate: entity.startDate,
			endDate: entity.endDate,
			statusEntries: entity.statusEntries,
			deletedAt: entity.deletedAt,
			version: entity.version,
		}
	}
}

import { injectable } from 'tsyringe-neo'
import { Handler, z, DrizzleClient } from '@bk-dash/core-typescript'

import { MonetaryAmountSchema } from '../../shared/objects'
import { OperationalCostRepository } from '../repositories/OperationalCostRepository'
import { OperationalCostCategory, OperationalCostPaymentStatus, OperationalCostRecurrency } from '@bk-dash/contracts-typescript/wire/enums'

export const GetOperationalCostsListInputSchema = z.object({
	storeId: z.uuid(),
	page: z.number().int().min(1).default(1),
	limit: z.number().int().min(1).max(200).default(50),
})

const OperationalCostItemSchema = z.object({
	operationalCostId: z.uuid(),
	category: z.enum(OperationalCostCategory),
	description: z.string(),
	amount: MonetaryAmountSchema,
	recurrency: z.enum(OperationalCostRecurrency),
	startDate: z.date(),
	endDate: z.date().nullable(),
	statusEntries: z.array(
		z.object({
			occurrenceDate: z.date(),
			status: z.enum(OperationalCostPaymentStatus),
		}),
	),
})

export const GetOperationalCostsListOutputSchema = z.object({
	total: z.number().int().min(0),
	items: z.array(OperationalCostItemSchema),
})

/** T27 OperationalCostsList. Lists non-deleted operational costs scoped to a store. */
@injectable()
export class GetOperationalCostsList extends Handler<
	typeof GetOperationalCostsListInputSchema,
	typeof GetOperationalCostsListOutputSchema
> {
	readonly name = 'get_operational_costs_list' as const
	readonly inputSchema = GetOperationalCostsListInputSchema
	readonly outputSchema = GetOperationalCostsListOutputSchema

	constructor(private readonly costs: OperationalCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: DrizzleClient): Promise<this['output']> {
		const result = await this.costs.list({ storeId: input.storeId, page: input.page, limit: input.limit }, tx)
		return {
			total: result.total,
			items: result.items.map(c => ({
				operationalCostId: c.id.value,
				category: c.category,
				description: c.description,
				amount: c.amount,
				recurrency: c.recurrency,
				startDate: c.startDate,
				endDate: c.endDate,
				statusEntries: c.statusEntries.map(e => ({
					occurrenceDate: e.occurrenceDate,
					status: e.status,
				})),
			})),
		}
	}
}

import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'

import { MonetaryAmountSchema } from '../../shared/objects'
import { OperationalCost } from '../entities/OperationalCost'
import { OperationalCostRepository } from '../repositories/OperationalCostRepository'
import { OperationalCostCreatedEvent } from '../events'
import { OperationalCostCategory, OperationalCostRecurrency } from '@bk-dash/contracts-typescript/wire/enums'

export const CreateOperationalCostInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	category: z.enum(OperationalCostCategory),
	description: z.string().min(1).max(500),
	amount: MonetaryAmountSchema.refine(m => m.amountCents > 0),
	recurrency: z.enum(OperationalCostRecurrency),
	startDate: z.date(),
	endDate: z.date().optional(),
})

export const CreateOperationalCostOutputSchema = z.object({
	operationalCostId: z.uuid(),
})

/**
 * C41 CreateOperationalCost. Instantiates the aggregate via
 * `OperationalCost.create(...)` (validates the date range), persists,
 * and emits OperationalCostCreatedEvent.
 */
@injectable()
export class CreateOperationalCost extends Handler<typeof CreateOperationalCostInputSchema, typeof CreateOperationalCostOutputSchema> {
	readonly name = 'create_operational_cost' as const
	readonly inputSchema = CreateOperationalCostInputSchema
	readonly outputSchema = CreateOperationalCostOutputSchema

	constructor(private readonly costs: OperationalCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const entity = OperationalCost.create({
				storeId: input.storeId,
				category: input.category,
				description: input.description,
				amount: input.amount,
				recurrency: input.recurrency,
				startDate: input.startDate,
				endDate: input.endDate,
			})
			await this.costs.save(entity, tx)

			await this.domainEventRepository.save(
				new OperationalCostCreatedEvent({
					entityId: entity.id.value,
					ownerId: input.storeId,
					payload: { operationalCost: entity.toJSON() },
				}),
				tx,
			)

			return { operationalCostId: entity.id.value }
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'

import { MonetaryAmountSchema } from '../../shared/objects'
import { OperationalCostRepository } from '../repositories/OperationalCostRepository'
import { OperationalCostUpdatedEvent } from '../events'
import type { FinanceApplicationErrors } from '../errors'
import { OperationalCostCategory, OperationalCostRecurrency } from '@bk-dash/contracts-typescript/wire/enums'

export const UpdateOperationalCostInputSchema = z.object({
	userId: z.uuid(),
	operationalCostId: z.uuid(),
	category: z.enum(OperationalCostCategory).optional(),
	description: z.string().min(1).max(500).optional(),
	amount: MonetaryAmountSchema.refine(m => m.amountCents > 0).optional(),
	recurrency: z.enum(OperationalCostRecurrency).optional(),
	startDate: z.date().optional(),
	endDate: z.date().nullable().optional(),
})

export const UpdateOperationalCostOutputSchema = z.void()

/** C42 UpdateOperationalCost. Patches the aggregate via `entity.update(patch)` which validates dates, then persists + emits OperationalCostUpdatedEvent unconditionally. */
@injectable()
export class UpdateOperationalCost extends Handler<typeof UpdateOperationalCostInputSchema, typeof UpdateOperationalCostOutputSchema> {
	readonly name = 'update_operational_cost' as const
	readonly inputSchema = UpdateOperationalCostInputSchema
	readonly outputSchema = UpdateOperationalCostOutputSchema

	constructor(private readonly costs: OperationalCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const entity = await this.costs.findById(input.operationalCostId, tx)
		if (!entity) {
			throw new BaseError<FinanceApplicationErrors>('OPERATIONAL_COST_NOT_FOUND')
		}

		entity.update({
			category: input.category,
			description: input.description,
			amount: input.amount,
			recurrency: input.recurrency,
			startDate: input.startDate,
			endDate: input.endDate,
		})

		await this.withTransaction(tx, async tx => {
			await this.costs.save(entity, tx)
			await this.domainEventRepository.save(
				new OperationalCostUpdatedEvent({
					entityId: entity.id.value,
					ownerId: entity.storeId.value,
					payload: { operationalCost: entity.toJSON() },
				}),
				tx,
			)
		})

		return
	}
}

