		})
	}

	update(patch: {
		category?: OperationalCostCategory
		description?: string
		amount?: { amountCents: number; currency: CurrencyCode }
		recurrency?: OperationalCostRecurrency
		startDate?: Date
		endDate?: Date | null
	}): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'cannot update a deleted OperationalCost')
		}
		const effectiveStart = patch.startDate ?? this.startDate
		const effectiveEnd = patch.endDate !== undefined ? patch.endDate : this.endDate
		if (effectiveEnd !== null && effectiveStart > effectiveEnd) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'startDate must be <= endDate')
		}
		if (patch.category !== undefined) {
			this.category = patch.category
		}
		if (patch.description !== undefined) {
			this.description = patch.description
		}
		if (patch.amount !== undefined) {
			this.amount = new MonetaryAmount(patch.amount)
		}
		if (patch.recurrency !== undefined) {
			this.recurrency = patch.recurrency
		}
		if (patch.startDate !== undefined) {
			this.startDate = patch.startDate
		}
		if (patch.endDate !== undefined) {
			this.endDate = patch.endDate
		}
		this.validate()
	}

	setStatus(occurrenceDate: Date, status: OperationalCostPaymentStatus): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'cannot toggle status on a deleted OperationalCost')
		}
		const i = this.statusEntries.findIndex(e => e.occurrenceDate.getTime() === occurrenceDate.getTime())
		if (i >= 0) this.statusEntries[i] = { occurrenceDate, status }
		else this.statusEntries.push({ occurrenceDate, status })
		this.validate()
	}

	delete(): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'OperationalCost already deleted')
		}
		this.deletedAt = new Date()
		this.validate()
	}

	get isDeleted(): boolean {
		return this.deletedAt !== null
	}
}

