	typeof ToggleOperationalCostStatusInputSchema,
	typeof ToggleOperationalCostStatusOutputSchema
> {
	readonly name = 'toggle_operational_cost_status' as const
	readonly inputSchema = ToggleOperationalCostStatusInputSchema
	readonly outputSchema = ToggleOperationalCostStatusOutputSchema

	constructor(private readonly costs: OperationalCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const entity = await this.costs.findById(input.operationalCostId, tx)
		if (!entity || entity.isDeleted) {
			throw new BaseError<FinanceApplicationErrors>('OPERATIONAL_COST_NOT_FOUND')
