import { injectable } from 'tsyringe-neo'
import { and, count, desc, eq, isNull, sql } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { operationalCosts } from '@bk-dash/contracts/db'
import { OperationalCostPaymentStatus } from '@bk-dash/contracts-typescript/wire/enums'
import { OperationalCost, OperationalCostSchema } from '../../entities/OperationalCost'
import { OperationalCostRepository, type OperationalCostListQuery, type OperationalCostListResult } from './OperationalCostRepository'

/**
 * Drizzle-backed OperationalCostRepository (iter 306 — paired with
 * the 0023 schema rename label→description + drop of payment_method
 * and active columns, bringing the table into agreement with the
 * entity contract).
 *
 * `list` filters out soft-deleted rows (`deletedAt IS NULL`) and
 * paginates newest-first by createdAt. The entity's `deletedAt` is
 * the canonical "is this row visible?" signal — there's no separate
 * `active` flag the spec aspired to but the aggregate never grew up
 * to need.
 *
 * `amountCents` round-trips via `Number()` / `BigInt()` because the
 * column is `bigint` (storage) while the entity carries `number`
 * (cents within JS safe-int range).
 */
@injectable()
export class DrizzleOperationalCostRepository extends OperationalCostRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<OperationalCost | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(operationalCosts).where(eq(operationalCosts.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async list(query: OperationalCostListQuery, tx?: DrizzleClient): Promise<OperationalCostListResult> {
		const dbc = tx ?? this.db
		const where = and(eq(operationalCosts.storeId, query.storeId), isNull(operationalCosts.deletedAt))
		const result = await tryCatchAsync(async () => {
			const offset = Math.max(0, (query.page - 1) * query.limit)
			const [items, totalRows] = await Promise.all([
				dbc.select().from(operationalCosts).where(where).orderBy(desc(operationalCosts.createdAt)).limit(query.limit).offset(offset),
				dbc
					.select({ value: count() })
					.from(operationalCosts)
					.where(where ?? sql`true`),
			])
			return { items, total: Number(totalRows[0]?.value ?? 0) }
		})
		if (!result.success) throw result.error
		return {
			total: result.data.total,
			items: result.data.items.map(r => this.toDomain(r)),
		}
	}

	async save(entity: OperationalCost, tx?: DrizzleClient): Promise<OperationalCost> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(operationalCosts)
				.values(data)
				.onConflictDoUpdate({
					target: operationalCosts.id,
					set: {
						storeId: data.storeId,
						description: data.description,
						category: data.category,
						recurrency: data.recurrency,
						amountCents: data.amountCents,
						currency: data.currency,
						startDate: data.startDate,
						endDate: data.endDate,
						statusEntries: data.statusEntries,
						deletedAt: data.deletedAt,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(operationalCosts).where(eq(operationalCosts.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof operationalCosts.$inferSelect): OperationalCost {
		const parsed = OperationalCostSchema.parse({
			storeId: row.storeId,
			description: row.description,
			category: row.category,
			recurrency: row.recurrency,
			amount: { amountCents: Number(row.amountCents), currency: row.currency },
			startDate: row.startDate,
			endDate: row.endDate,
			// statusEntries is JSONB: occurrenceDate round-trips as an ISO string, so
			// coerce it back to a Date before the entity schema (z.date()) parses it.
			statusEntries: ((row.statusEntries ?? []) as Array<{ occurrenceDate: string; status: OperationalCostPaymentStatus }>).map(e => ({
				occurrenceDate: new Date(e.occurrenceDate),
				status: e.status,
			})),
			deletedAt: row.deletedAt,
		})
		return new OperationalCost({
			...parsed,
			id: row.id,
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: OperationalCost): typeof operationalCosts.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			description: entity.description,
			category: entity.category,
			recurrency: entity.recurrency,
			amountCents: BigInt(entity.amount.amountCents),
			currency: entity.amount.currency,
			startDate: entity.startDate,
			endDate: entity.endDate,
			statusEntries: entity.statusEntries,
			deletedAt: entity.deletedAt,
			version: entity.version,
		}
	}
}

