import { injectable } from 'tsyringe-neo'
import { Handler, z, DrizzleClient } from '@bk-dash/core-typescript'
import { and, gte, inArray, lte, sql } from 'drizzle-orm'
import { adSpends, orders } from '@bk-dash/contracts/db'
import { AnalyticsFrequency, CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

export const GetProfitMarginReportInputSchema = z.object({
	storeIds: z.array(z.uuid()).min(1),
	from: z.date(),
	to: z.date(),
	frequency: z.enum(AnalyticsFrequency),
})

export const GetProfitMarginReportOutputSchema = z.object({
	reportingCurrency: z.enum(CurrencyCode),
	periods: z.array(
		z.object({
			periodStart: z.iso.date(),
			revenueAmountCents: z.number().int(),
			costAmountCents: z.number().int(),
			taxAmountCents: z.number().int(),
			feesAmountCents: z.number().int(),
			marketingAmountCents: z.number().int(),
			operationalAmountCents: z.number().int(),
			warrantyAmountCents: z.number().int(),
			profitAmountCents: z.number().int(),
			marginPercent: z.number(),
		}),
	),
})

interface PeriodRow {
	periodStart: string
	revenueAmountCents: number
	costAmountCents: number
	taxAmountCents: number
	feesAmountCents: number
	marketingAmountCents: number
	operationalAmountCents: number
	warrantyAmountCents: number
	profitAmountCents: number
	marginPercent: number
}

/**
 * T33 ProfitMarginReport. Time-bucketed roll-up of revenue + marketing
 * spend over the requested frequency. Cost / tax / fees / operational /
 * warranty fields stay at 0 today — they need:
 *   - Cost: ProductCost line-item attribution (orders.lines × ProductCost option pick)
 *   - Tax: per-Store Taxes rate × revenue
 *   - Fees: FeesConfiguration gateway/checkout/shipping per order
 *   - Operational: per-period OperationalCost spread
 *   - Warranty: per-period WarrantyReserve rate × revenue
 *
 * The aggregations to land them all exist as separate use cases /
 * repos already; the cross-aggregate join lands in a follow-up that
 * introduces an Analytics application service to keep this controller
 * decoupled from the source BCs.
 *
 * `profitAmountCents = revenue - (cost + tax + fees + marketing +
 * operational + warranty)`. `marginPercent = profit / revenue * 100`.
 */
@injectable()
export class GetProfitMarginReport extends Handler<typeof GetProfitMarginReportInputSchema, typeof GetProfitMarginReportOutputSchema> {
	readonly name = 'get_profit_margin_report' as const
	readonly inputSchema = GetProfitMarginReportInputSchema
	readonly outputSchema = GetProfitMarginReportOutputSchema

	constructor(private readonly db: DrizzleClient) {
		super()
	}

	protected async handle(input: this['input'], tx?: DrizzleClient): Promise<this['output']> {
		const dbc = tx ?? this.db
		const fromDate = input.from
		const toDate = input.to
		const unit = bucketUnit(input.frequency as AnalyticsFrequency)
		const unitLiteral = sql.raw(`'${unit}'`)

		const revenueBucket = sql<string>`to_char(date_trunc(${unitLiteral}, ${orders.externalCreatedAt}), 'YYYY-MM-DD')`
		const marketingBucket = sql<string>`to_char(date_trunc(${unitLiteral}, ${adSpends.bucketStart}), 'YYYY-MM-DD')`

		const [revenueRows, marketingRows] = await Promise.all([
			dbc
				.select({
					period: revenueBucket,
					total: sql<string>`sum(${orders.totalCents})`,
				})
				.from(orders)
				.where(and(inArray(orders.storeId, input.storeIds), gte(orders.externalCreatedAt, fromDate), lte(orders.externalCreatedAt, toDate)))
				.groupBy(revenueBucket),
			dbc
				.select({
					period: marketingBucket,
					total: sql<string>`sum(${adSpends.amountCents})`,
				})
				.from(adSpends)
				.where(and(inArray(adSpends.storeId, input.storeIds), gte(adSpends.bucketStart, fromDate), lte(adSpends.bucketStart, toDate)))
				.groupBy(marketingBucket),
		])

		const byPeriod = new Map<string, PeriodRow>()
		const ensure = (period: string): PeriodRow => {
			if (!byPeriod.has(period)) {
				byPeriod.set(period, {
					periodStart: period,
					revenueAmountCents: 0,
					costAmountCents: 0,
					taxAmountCents: 0,
					feesAmountCents: 0,
					marketingAmountCents: 0,
					operationalAmountCents: 0,
					warrantyAmountCents: 0,
					profitAmountCents: 0,
					marginPercent: 0,
				})
			}
			return byPeriod.get(period)!
		}

		for (const r of revenueRows as Array<{ period: string; total: string | null }>) {
			ensure(r.period).revenueAmountCents = Number(r.total ?? 0)
		}
		for (const r of marketingRows as Array<{ period: string; total: string | null }>) {
			ensure(r.period).marketingAmountCents = Number(r.total ?? 0)
		}

		for (const p of byPeriod.values()) {
			const deductions =
				p.costAmountCents + p.taxAmountCents + p.feesAmountCents + p.marketingAmountCents + p.operationalAmountCents + p.warrantyAmountCents
			p.profitAmountCents = p.revenueAmountCents - deductions
			p.marginPercent = p.revenueAmountCents > 0 ? (p.profitAmountCents / p.revenueAmountCents) * 100 : 0
		}

		const periods = [...byPeriod.values()].sort((a, b) => (a.periodStart < b.periodStart ? -1 : 1))
		return {
			reportingCurrency: CurrencyCode.USD,
			periods,
		}
	}
}

const BUCKET_UNIT: Record<AnalyticsFrequency, string> = {
	[AnalyticsFrequency.HOURLY]: 'hour',
	[AnalyticsFrequency.DAILY]: 'day',
	[AnalyticsFrequency.WEEKLY]: 'week',
	[AnalyticsFrequency.MONTHLY]: 'month',
	[AnalyticsFrequency.YEARLY]: 'year',
}

function bucketUnit(freq: AnalyticsFrequency): string {
	return BUCKET_UNIT[freq]
}

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import {
	CurrencyCode,
	OperationalCostCategory,
	OperationalCostPaymentStatus,
	OperationalCostRecurrency,
} from '@bk-dash/contracts-typescript/wire/enums'
import { OperationalCost } from '../../entities/OperationalCost'
import { OperationalCostRepository } from './OperationalCostRepository'

const STORE_A = testId('store', '1')
const STORE_B = testId('store', '2')

describe('DrizzleOperationalCostRepository', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let repo: OperationalCostRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		repo = testBed.resolve(OperationalCostRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	function build(opts: {
		storeId?: string
		description?: string
		amount?: { amountCents: number; currency: CurrencyCode }
		startDate?: string
	}): OperationalCost {
		return OperationalCost.create({
			storeId: opts.storeId ?? STORE_A,
			category: OperationalCostCategory.RENT,
			description: opts.description ?? 'May rent',
			amount: opts.amount ?? { amountCents: 100_000, currency: CurrencyCode.USD },
			recurrency: OperationalCostRecurrency.MONTHLY,
			startDate: new Date(opts.startDate ?? '2026-05-01'),
		})
	}

	describe('save + findById', () => {
		it('round-trips through Drizzle (bigint amountCents preserved)', async () => {
			const entity = build({ amount: { amountCents: 500_000, currency: CurrencyCode.USD }, description: 'Salary' })
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.storeId.value).toBe(STORE_A)
			expect(fetched?.description).toBe('Salary')
			expect(fetched?.amount.amountCents).toBe(500_000) // bigint → number round-trip
			expect(fetched?.amount.currency).toBe(CurrencyCode.USD)
			expect(fetched?.recurrency).toBe(OperationalCostRecurrency.MONTHLY)
			expect(fetched?.startDate).toEqual(new Date('2026-05-01'))
			expect(fetched?.deletedAt).toBeNull()
		})

		it('returns undefined when no row matches', async () => {
			const r = await repo.findById(testId())
			expect(r).toBeUndefined()
		})

		it('UPSERT persists update() — description + amount bumped', async () => {
			const entity = build({ description: 'old', amount: { amountCents: 100_000, currency: CurrencyCode.USD } })
			await repo.save(entity)

			entity.update({ description: 'new', amount: { amountCents: 200_000, currency: CurrencyCode.USD } })
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.description).toBe('new')
			expect(fetched?.amount.amountCents).toBe(200_000)
			expect(fetched?.version).toBeGreaterThan(1)
		})

		it('round-trips statusEntries jsonb with occurrenceDate key', async () => {
			const entity = build({})
			entity.setStatus(new Date('2026-05-01T00:00:00.000Z'), OperationalCostPaymentStatus.PAID)
			entity.setStatus(new Date('2026-06-01T00:00:00.000Z'), OperationalCostPaymentStatus.UNPAID)
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.statusEntries).toHaveLength(2)
			const paid = fetched?.statusEntries.find(e => e.occurrenceDate.getTime() === new Date('2026-05-01T00:00:00.000Z').getTime())
			expect(paid?.status).toBe(OperationalCostPaymentStatus.PAID)
		})

		it('UPSERT persists delete() — deletedAt set, soft-delete', async () => {
			const entity = build({})
			await repo.save(entity)

			entity.delete()
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.deletedAt).not.toBeNull()
		})
	})

	describe('list', () => {
		it('returns empty list when store has none', async () => {
			const r = await repo.list({ storeId: STORE_A, page: 1, limit: 10 })
			expect(r.total).toBe(0)
			expect(r.items).toEqual([])
		})

		it('filters out soft-deleted rows', async () => {
			const live = build({ description: 'live' })
			await repo.save(live)

			const deleted = build({ description: 'deleted' })
			deleted.delete()
			await repo.save(deleted)

			const r = await repo.list({ storeId: STORE_A, page: 1, limit: 10 })
			expect(r.total).toBe(1)
			expect(r.items[0]?.description).toBe('live')
		})

		it('isolates by storeId', async () => {
			await repo.save(build({ storeId: STORE_A, description: 'A' }))
			await repo.save(build({ storeId: STORE_B, description: 'B' }))

			const a = await repo.list({ storeId: STORE_A, page: 1, limit: 10 })
			expect(a.total).toBe(1)
			expect(a.items[0]?.description).toBe('A')
		})

		it('paginates: total reflects unpaged match count', async () => {
			for (let i = 0; i < 5; i++) await repo.save(build({ description: `c${i}` }))

			const page1 = await repo.list({ storeId: STORE_A, page: 1, limit: 2 })
			const page3 = await repo.list({ storeId: STORE_A, page: 3, limit: 2 })

			expect(page1.total).toBe(5)
			expect(page1.items).toHaveLength(2)
			expect(page3.items).toHaveLength(1)
		})
	})

	describe('delete', () => {
		it('hard-removes the row + subsequent findById returns undefined', async () => {
			const entity = build({})
			await repo.save(entity)
			await repo.delete(entity.id.value)
			expect(await repo.findById(entity.id.value)).toBeUndefined()
		})
	})
})

