import { OperationalCostCreatedEvent } from '../events'
import { OperationalCostCategory, OperationalCostRecurrency } from '@bk-dash/contracts-typescript/wire/enums'

export const CreateOperationalCostInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
