})

/**
 * C41 CreateOperationalCost. Instantiates the aggregate via
 * `OperationalCost.create(...)` (validates the date range), persists,
 * and emits OperationalCostCreatedEvent.
 */
@injectable()
export class CreateOperationalCost extends Handler<typeof CreateOperationalCostInputSchema, typeof CreateOperationalCostOutputSchema> {
	readonly name = 'create_operational_cost' as const
	readonly inputSchema = CreateOperationalCostInputSchema
	readonly outputSchema = CreateOperationalCostOutputSchema

	constructor(private readonly costs: OperationalCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
