import { OperationalCostRecurrency } from '@bk-dash/contracts-typescript/wire/enums'

/**
 * Pure recurrence math for OperationalCost occurrences. Occurrences are
 * **never materialized to storage** — they are derived at runtime from
 * `(recurrency, startDate, effectiveEnd)`. Two strategies live here:
 *
 *  1. **Windowed expansion** (`occurrenceWindow`) — materializes only the
 *     requested page of occurrence dates, so a DAILY cost spanning years
 *     never blows up memory: at most `limit` `Date`s are allocated.
 *  2. **Multiplication counting** (`countOccurrencesInRange`) — returns the
 *     occurrence count for a range with O(1) arithmetic (no materialization),
 *     so dashboards compute `count × amount` instead of summing rows.
 *
 * Ranges are half-open on the query window — `from <= o < to` — and bounded
 * by the series: `startDate <= o <= effectiveEnd`. `effectiveEnd` is the
 * cost's `endDate`, or "today" for an open-ended (still-recurring) cost.
 */

const DAY_MS = 86_400_000

/** Fixed-day steps — occurrence index maps to a constant millisecond offset. */
const STEP_DAYS: Partial<Record<OperationalCostRecurrency, number>> = {
	[OperationalCostRecurrency.DAILY]: 1,
	[OperationalCostRecurrency.WEEKLY]: 7,
}

/** Calendar-month steps — occurrence index maps to N added months (day clamped). */
const STEP_MONTHS: Partial<Record<OperationalCostRecurrency, number>> = {
	[OperationalCostRecurrency.MONTHLY]: 1,
	[OperationalCostRecurrency.BIMESTER]: 2,
	[OperationalCostRecurrency.TRIMESTER]: 3,
	[OperationalCostRecurrency.SEMESTER]: 6,
	[OperationalCostRecurrency.YEARLY]: 12,
}

/** ONCE / NONE collapse to a single occurrence at `startDate`. */
export function isRecurring(recurrency: OperationalCostRecurrency): boolean {
	return STEP_DAYS[recurrency] !== undefined || STEP_MONTHS[recurrency] !== undefined
}

function addMonths(d: Date, months: number): Date {
	const targetMonthIndex = d.getUTCMonth() + months
	const targetYear = d.getUTCFullYear() + Math.floor(targetMonthIndex / 12)
	const targetMonth = ((targetMonthIndex % 12) + 12) % 12
	const lastDay = new Date(Date.UTC(targetYear, targetMonth + 1, 0)).getUTCDate()
	return new Date(
		Date.UTC(
			targetYear,
			targetMonth,
			Math.min(d.getUTCDate(), lastDay),
			d.getUTCHours(),
			d.getUTCMinutes(),
			d.getUTCSeconds(),
			d.getUTCMilliseconds(),
		),
	)
}

function monthDiff(a: Date, b: Date): number {
	return (b.getUTCFullYear() - a.getUTCFullYear()) * 12 + (b.getUTCMonth() - a.getUTCMonth())
}

/** The i-th occurrence (i >= 0) of a series, or null when i is out of range (single-occurrence series). */
export function occurrenceAt(start: Date, recurrency: OperationalCostRecurrency, i: number): Date | null {
	const days = STEP_DAYS[recurrency]
	if (days !== undefined) return new Date(start.getTime() + i * days * DAY_MS)
	const months = STEP_MONTHS[recurrency]
	if (months !== undefined) return addMonths(start, i * months)
	return i === 0 ? new Date(start.getTime()) : null
}

/** Smallest index i >= 0 with `occurrenceAt(i) >= bound` (recurring series only). */
function firstIndexGE(start: Date, recurrency: OperationalCostRecurrency, bound: Date): number {
	if (bound.getTime() <= start.getTime()) return 0
	const days = STEP_DAYS[recurrency]
	if (days !== undefined) return Math.ceil((bound.getTime() - start.getTime()) / (days * DAY_MS))
	const months = STEP_MONTHS[recurrency]!
	let i = Math.max(0, Math.floor(monthDiff(start, bound) / months))
	while (i > 0 && occurrenceAt(start, recurrency, i - 1)!.getTime() >= bound.getTime()) i--
	while (occurrenceAt(start, recurrency, i)!.getTime() < bound.getTime()) i++
	return i
}

/** Largest index i >= 0 with `occurrenceAt(i) <= bound`, or -1 (recurring series only). */
function lastIndexLE(start: Date, recurrency: OperationalCostRecurrency, bound: Date): number {
	if (bound.getTime() < start.getTime()) return -1
	const days = STEP_DAYS[recurrency]
	if (days !== undefined) return Math.floor((bound.getTime() - start.getTime()) / (days * DAY_MS))
	const months = STEP_MONTHS[recurrency]!
	let i = Math.max(0, Math.floor(monthDiff(start, bound) / months))
	while (i > 0 && occurrenceAt(start, recurrency, i)!.getTime() > bound.getTime()) i--
	while (occurrenceAt(start, recurrency, i + 1)!.getTime() <= bound.getTime()) i++
	return i
}

interface RangeInput {
	start: Date
	effectiveEnd: Date
	recurrency: OperationalCostRecurrency
	from: Date
	to: Date
}

/**
 * Index range `[firstIdx, lastIdx]` of occurrences satisfying
 * `max(from, start) <= o`, `o < to` and `o <= effectiveEnd`.
 * `lastIdx < firstIdx` means the range is empty.
 */
function boundedIndices({ start, effectiveEnd, recurrency, from, to }: RangeInput): { firstIdx: number; lastIdx: number } {
	const lower = from.getTime() > start.getTime() ? from : start

	if (!isRecurring(recurrency)) {
		const o = start.getTime()
		const inRange = o >= lower.getTime() && o < to.getTime() && o <= effectiveEnd.getTime()
		return inRange ? { firstIdx: 0, lastIdx: 0 } : { firstIdx: 0, lastIdx: -1 }
	}

	// Upper bound: occurrence < to (half-open) AND <= effectiveEnd (inclusive).
	const upperInclusive = new Date(Math.min(effectiveEnd.getTime(), to.getTime() - 1))
	return {
		firstIdx: firstIndexGE(start, recurrency, lower),
		lastIdx: lastIndexLE(start, recurrency, upperInclusive),
	}
}

/** O(1) occurrence count in range — the multiplication strategy's counter. No `Date`s materialized. */
export function countOccurrencesInRange(start: Date, effectiveEnd: Date, recurrency: OperationalCostRecurrency, from: Date, to: Date): number {
	const { firstIdx, lastIdx } = boundedIndices({ start, effectiveEnd, recurrency, from, to })
	return Math.max(0, lastIdx - firstIdx + 1)
}

/**
 * Windowed expansion — the listing strategy. Returns the total count plus
 * only the `page`/`limit` slice of occurrence dates (at most `limit` `Date`s).
 */
export function occurrenceWindow(
	start: Date,
	effectiveEnd: Date,
	recurrency: OperationalCostRecurrency,
	from: Date,
	to: Date,
	page: number,
	limit: number,
): { total: number; dates: Date[] } {
	const { firstIdx, lastIdx } = boundedIndices({ start, effectiveEnd, recurrency, from, to })
	const total = Math.max(0, lastIdx - firstIdx + 1)
	const offset = Math.max(0, (page - 1) * limit)
	const dates: Date[] = []
	for (let i = firstIdx + offset; i <= lastIdx && dates.length < limit; i++) {
		dates.push(occurrenceAt(start, recurrency, i)!)
	}
	return { total, dates }
}

