import { pgSchema, uuid, text, timestamp, integer, bigint, jsonb, doublePrecision, index } from 'drizzle-orm/pg-core'

/**
 * `finance` is BK Dash's BC8 Finance schema.
 *
 * All TS-owned merchant aggregates — no Go writes here. The Go-side
 * sync engine emits provider-reported amounts (gateway fees inline in
 * OrderTransaction, etc.); Finance owns the merchant-side
 * configuration that turns those amounts into profit margins.
 *
 * Tables:
 *   - `taxes`               — Store-scoped, time-effective tax regime
 *   - `fees_configuration`  — Store-scoped header + typed sub-fee
 *                             jsonb arrays (gateway / checkout / shipping)
 *   - `operational_costs`   — merchant cost ledger w/ status entries
 *   - `warranty_reserves`   — % of revenue reserved per Store (time-effective)
 *   - `fx_rates`            — append-only, query by (from, to, startDate ≤ at)
 */
export const financeSchema = pgSchema('finance')

/**
 * `taxes` — one row per (storeId, startDate slice). `endDate` nullable
 * means "still effective". Queries pick the row matching
 * `startDate <= date AND (endDate IS NULL OR endDate > date)`.
 */
export const taxes = financeSchema.table(
	'taxes',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// TaxType enum (NONE | PRESUMED_PROFIT | REAL_PROFIT).
		type: text('type').notNull(),
		// TaxDeductionType enum (NONE | PRODUCT_COST | PRODUCT_COST_AND_MARKETING).
		deductionType: text('deduction_type').notNull(),

		// Effective tax rate as a fraction 0..1 (e.g. 0.085 = 8.5%). Stored
		// as double precision because tax calculations vary in precision
		// per jurisdiction and a fixed-point representation would force
		// us to pick a unit per market.
		rate: doublePrecision('rate').notNull(),

		// Spec §4 BC8 `Taxes` aggregate: per-Store profit multiplier
		// applied to revenue tax (e.g. 1.0 = neutral, 1.15 = 15% safety
		// buffer). Stored alongside `rate` to keep T25 reads to a single
		// SELECT. Default 1.0 = no multiplier so historical rows backfill
		// to a neutral value.
		revenueTaxMultiplier: doublePrecision('revenue_tax_multiplier').notNull().default(1.0),

		// Spec §4 BC8 + T25: per-platform marketing-tax overrides keyed by
		// MarketingPlatform (META | GOOGLE_ADS | TIKTOK). Empty map = no
		// per-platform overrides — fall back to `rate`. JSONB shape is
		// `Partial<Record<MarketingPlatform, number>>` per spec line 836.
		marketingTaxRatePerPlatform: jsonb('marketing_tax_rate_per_platform').notNull().default({}),

		startDate: timestamp('start_date', { withTimezone: true }).notNull(),
		endDate: timestamp('end_date', { withTimezone: true }),

		// Audit pointer to the user who applied the most recent change.
		// Nullable (no FK) — preserves audit trail when a user is removed.
		updatedByUserId: text('updated_by_user_id'),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeIdx: index('taxes_store_id_idx').on(t.storeId),
		// Time-effective lookup index.
		storeStartDateIdx: index('taxes_store_start_date_idx').on(t.storeId, t.startDate),
	}),
)

/**
 * `fees_configuration` — single header row per Store with three typed
 * jsonb arrays of sub-fees:
 *
 *   - gateway_fees: GatewayFee[]
 *       { platform: PaymentGateway, paymentMethod: PaymentMethod,
 *         percentage: number, fixed: { amountCents, currency }[] }
 *   - checkout_fees: CheckoutFee[]
 *       { platform: CheckoutPlatform, rate: number }
 *   - shipping_fees: ShippingFee[]
 *       { type: ShippingCostType, value: ShippingCostValue }
 *
 * jsonb chosen over separate child tables because (a) read shape is
 * always "the full configuration for one Store", and (b) the
 * per-platform sub-shapes vary (e.g. ShippingCostValue is a 4-variant
 * discriminated union from spec — modeling it relationally would
 * require multiple child tables for a write that happens N×/year.)
 */
export const feesConfiguration = financeSchema.table(
	'fees_configuration',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		gatewayFees: jsonb('gateway_fees').notNull(),
		checkoutFees: jsonb('checkout_fees').notNull(),
		// Singular: the spec's FeesConfiguration carries one shipping
		// fee per row (matches the entity's `shippingFee` field).
		// Stored as a nullable jsonb so the "no shipping fee
		// configured yet" state encodes as JSON null.
		shippingFee: jsonb('shipping_fee'),

		// Spec §4 BC8 + C40: time-effective semantics matching `taxes`.
		// Multiple rows per Store; the active one has `endDate IS NULL`.
		// C40 closes the previous row's endDate and inserts a new one.
		// Default startDate = row insertion time (safe for historical
		// single-row data migrated forward — it becomes the first slice).
		startDate: timestamp('start_date', { withTimezone: true }).notNull().defaultNow(),
		endDate: timestamp('end_date', { withTimezone: true }),

		// Audit pointer (same rationale as `taxes.updatedByUserId`).
		updatedByUserId: text('updated_by_user_id'),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// Time-effective lookup: (storeId, startDate) replaces the previous
		// `(storeId) UNIQUE` constraint. Active-row lookup uses
		// `WHERE storeId = ? AND endDate IS NULL`.
		storeStartDateIdx: index('fees_configuration_store_start_date_idx').on(t.storeId, t.startDate),
	}),
)

/**
 * `operational_costs` — merchant cost ledger. Each row is one cost
 * line item with its own recurrence pattern. Occurrences are derived
 * at runtime (never stored); `status_overrides` is a jsonb array of
 * { occurrenceDate, status } holding only the per-occurrence deviations
 * from the default status (e.g. mark October's RENT as CANCELLED).
 */
export const operationalCosts = financeSchema.table(
	'operational_costs',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// Free-form merchant description ("November salary advance",
		// "Adobe CC", …). category is the enum classification.
		description: text('description').notNull(),
		category: text('category').notNull(),

		// OperationalCostRecurrency enum (ONCE | DAILY | WEEKLY | … |
		// YEARLY | NONE).
		recurrency: text('recurrency').notNull(),

		amountCents: bigint('amount_cents', { mode: 'bigint' }).notNull(),
		currency: text('currency').notNull(),

		// First occurrence date. For recurring costs the date implies
		// each future occurrence (e.g. MONTHLY starting Jan 15 →
		// Feb 15, Mar 15, …).
		startDate: timestamp('start_date', { withTimezone: true }).notNull(),
		// Optional terminator for recurring costs ("stop billing this
		// after X"); nullable = still recurring.
		endDate: timestamp('end_date', { withTimezone: true }),

		// jsonb array of { occurrenceDate, status } per occurrence —
		// matches the OperationalCost entity's statusEntries shape
		// verbatim. Status uses OperationalCostPaymentStatus
		// (PAID | UNPAID | OVERDUE | CANCELLED).
		statusEntries: jsonb('status_entries').notNull(),

		// Soft-delete timestamp. T27 ListOperationalCosts filters out
		// rows where this is non-null — the entity uses `deletedAt`
		// alone as the "is this row visible?" signal (no separate
		// `active` flag).
		deletedAt: timestamp('deleted_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeIdx: index('operational_costs_store_id_idx').on(t.storeId),
		categoryIdx: index('operational_costs_category_idx').on(t.category),
		// Date scans for analytics rollups.
		startDateIdx: index('operational_costs_start_date_idx').on(t.startDate),
	}),
)

/**
 * `warranty_reserves` — per-Store percentage of revenue reserved for
 * warranty claims. Time-effective (multiple rows per Store; queries
 * pick the row whose start_date ≤ now AND (end_date IS NULL OR
 * end_date > now)).
 */
export const warrantyReserves = financeSchema.table(
	'warranty_reserves',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// Fraction 0..1 of revenue to reserve. Same precision rationale as
		// `taxes.rate`.
		rate: doublePrecision('rate').notNull(),

		// Spec § BC8 BC and the WarrantyReserve entity name the
		// time-effective window `effectiveFrom`/`effectiveTo` to
		// distinguish it from the soft-delete `deletedAt` timestamp.
		// (Taxes uses `start_date`/`end_date` because it has no soft
		// delete; reusing the same names here would conflate the two
		// audit dimensions.)
		effectiveFrom: timestamp('effective_from', { withTimezone: true }).notNull(),
		effectiveTo: timestamp('effective_to', { withTimezone: true }),
		// Soft-delete timestamp. listByStoreId filters out rows where
		// this is non-null; the supersession path uses effectiveTo
		// (not deletedAt) so historical analytics keep the row
		// visible.
		deletedAt: timestamp('deleted_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeEffectiveFromIdx: index('warranty_reserves_store_effective_from_idx').on(t.storeId, t.effectiveFrom),
	}),
)

/**
 * `fx_rates` — append-only currency conversion source of truth.
 *
 * Hourly CaptureFxRates cron emits rows from CURRENCY_API; merchants
 * may insert MANUAL overrides; providers may report rates inline
 * (PROVIDER_REPORTED, captured during transaction ingest).
 *
 * Queried with the canonical pattern:
 *   SELECT * FROM fx_rates
 *    WHERE from_currency = ? AND to_currency = ?
 *      AND start_date <= ?
 *    ORDER BY start_date DESC LIMIT 1
 *
 * The composite index on (from_currency, to_currency, start_date DESC)
 * makes that query a single-page seek.
 */
export const fxRates = financeSchema.table(
	'fx_rates',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		fromCurrency: text('from_currency').notNull(),
		toCurrency: text('to_currency').notNull(),

		// Conversion rate: 1 unit of fromCurrency = `rate` units of
		// toCurrency. Stored as `text` to preserve provider-side
		// decimal precision verbatim (e.g. '5.10' stays '5.10', not
		// coerced to 5.1). Queries never sort or aggregate on rate
		// (ORDER BY runs on start_date) so the lack of numeric
		// semantics is fine. The FxRate entity carries `rate: string`
		// matching this column.
		rate: text('rate').notNull(),

		// FxRateSource enum (CURRENCY_API | MANUAL | PROVIDER_REPORTED).
		source: text('source').notNull(),

		// When this rate became effective. Multiple rows may exist for
		// the same currency pair; queries pick the most recent ≤ desired
		// timestamp.
		startDate: timestamp('start_date', { withTimezone: true }).notNull(),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
	},
	t => ({
		// Canonical query index — covers the "find rate at time T" path.
		pairStartDateIdx: index('fx_rates_pair_start_date_idx').on(t.fromCurrency, t.toCurrency, t.startDate),
		sourceIdx: index('fx_rates_source_idx').on(t.source),
	}),
)

