						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(operationalCosts).where(eq(operationalCosts.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof operationalCosts.$inferSelect): OperationalCost {
		const parsed = OperationalCostSchema.parse({
			storeId: row.storeId,
			description: row.description,
			category: row.category,
			recurrency: row.recurrency,
			amount: { amountCents: Number(row.amountCents), currency: row.currency },
			startDate: row.startDate,
			endDate: row.endDate,
			// statusOverrides is JSONB: occurrenceDate round-trips as an ISO string, so
			// coerce it back to a Date before the entity schema (z.date()) parses it.
			statusOverrides: ((row.statusOverrides ?? []) as Array<{ occurrenceDate: string; status: OperationalCostPaymentStatus }>).map(o => ({
				occurrenceDate: new Date(o.occurrenceDate),
				status: o.status,
			})),
			deletedAt: row.deletedAt,
		})
		return new OperationalCost({
			...parsed,
			id: row.id,
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: OperationalCost): typeof operationalCosts.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			description: entity.description,
			category: entity.category,
			recurrency: entity.recurrency,
			amountCents: BigInt(entity.amount.amountCents),
			currency: entity.amount.currency,
			startDate: entity.startDate,
			endDate: entity.endDate,
			statusEntries: entity.statusEntries,
			deletedAt: entity.deletedAt,
			version: entity.version,
		}
	}
}

