import type { Transaction } from '@bk-dash/core-typescript'
import { OperationalCost } from '../../entities/OperationalCost'
import { OperationalCostRepository, type OperationalCostListQuery, type OperationalCostListResult } from './OperationalCostRepository'

@injectable()
export class MockOperationalCostRepository extends OperationalCostRepository {
	private rows = new Map<string, OperationalCost>()

	async findById(id: string, _tx?: Transaction): Promise<OperationalCost | undefined> {
		return this.rows.get(id)
	}

	async list(query: OperationalCostListQuery, _tx?: Transaction): Promise<OperationalCostListResult> {
		const matched = [...this.rows.values()].filter(c => c.storeId.value === query.storeId && !c.isDeleted)
		const start = (query.page - 1) * query.limit
		return { total: matched.length, items: matched.slice(start, start + query.limit) }
	}

	async save(entity: OperationalCost, _tx?: Transaction): Promise<OperationalCost> {
		entity.incrementVersion()
		this.rows.set(entity.id.value, entity)
		return entity
	}

	async delete(id: string, _tx?: Transaction): Promise<void> {
		this.rows.delete(id)
	}

	seed(entity: OperationalCost): void {
		this.rows.set(entity.id.value, entity)
	}

	clear(): void {
		this.rows.clear()
	}
}

