import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'

import { OperationalCostRepository } from '../repositories/OperationalCostRepository'
import { OperationalCostStatusOverriddenEvent } from '../events'
import type { FinanceApplicationErrors } from '../errors'
import { OperationalCostPaymentStatus } from '@bk-dash/contracts-typescript/wire/enums'

export const SetOperationalCostStatusOverrideInputSchema = z.object({
	userId: z.uuid(),
	operationalCostId: z.uuid(),
	occurrenceDate: z.date(),
	status: z.enum(OperationalCostPaymentStatus),
})

export const SetOperationalCostStatusOverrideOutputSchema = z.void()

/**
 * C44 SetOperationalCostStatusOverride. Records a per-occurrence status
 * deviation for a runtime-derived occurrence. Setting it back to the
 * default status clears the override (exclusion stays minimal).
 */
@injectable()
export class SetOperationalCostStatusOverride extends Handler<
	typeof SetOperationalCostStatusOverrideInputSchema,
	typeof SetOperationalCostStatusOverrideOutputSchema
> {
	readonly name = 'set_operational_cost_status_override' as const
	readonly inputSchema = SetOperationalCostStatusOverrideInputSchema
	readonly outputSchema = SetOperationalCostStatusOverrideOutputSchema

	constructor(private readonly costs: OperationalCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const entity = await this.costs.findById(input.operationalCostId, tx)
		if (!entity || entity.isDeleted) {
			throw new BaseError<FinanceApplicationErrors>('OPERATIONAL_COST_NOT_FOUND')
		}

		await this.withTransaction(tx, async tx => {
			entity.setStatusOverride(input.occurrenceDate, input.status)
			await this.costs.save(entity, tx)
			await this.domainEventRepository.save(
				new OperationalCostStatusOverriddenEvent({
					entityId: entity.id.value,
					ownerId: entity.storeId.value,
					payload: {
						operationalCostId: entity.id.value,
						storeId: entity.storeId.value,
						occurrenceDate: input.occurrenceDate,
						status: input.status,
					},
				}),
				tx,
			)
		})

		return
	}
}

