		if (!entity || entity.isDeleted) {
			throw new BaseError<FinanceApplicationErrors>('OPERATIONAL_COST_NOT_FOUND')
		}

		return entity.expandOccurrences({ from: input.from, to: input.to, page: input.page, limit: input.limit })
	}
}

