import { injectable } from 'tsyringe-neo'
import { Handler, z, DrizzleClient } from '@bk-dash/core-typescript'
import { and, gte, inArray, lte, sql } from 'drizzle-orm'
import { adSpends, orders } from '@bk-dash/contracts/db'
import { AnalyticsFrequency, CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

export const GetProfitMarginReportInputSchema = z.object({
	storeIds: z.array(z.uuid()).min(1),
	from: z.date(),
	to: z.date(),
	frequency: z.enum(AnalyticsFrequency),
})

export const GetProfitMarginReportOutputSchema = z.object({
	reportingCurrency: z.enum(CurrencyCode),
	periods: z.array(
		z.object({
			periodStart: z.iso.date(),
			revenueAmountCents: z.number().int(),
			costAmountCents: z.number().int(),
			taxAmountCents: z.number().int(),
			feesAmountCents: z.number().int(),
			marketingAmountCents: z.number().int(),
			operationalAmountCents: z.number().int(),
			warrantyAmountCents: z.number().int(),
			profitAmountCents: z.number().int(),
			marginPercent: z.number(),
		}),
	),
})

interface PeriodRow {
	periodStart: string
	revenueAmountCents: number
	costAmountCents: number
	taxAmountCents: number
	feesAmountCents: number
	marketingAmountCents: number
	operationalAmountCents: number
	warrantyAmountCents: number
	profitAmountCents: number
	marginPercent: number
}

/**
 * T33 ProfitMarginReport. Time-bucketed roll-up of revenue + marketing
 * spend over the requested frequency. Cost / tax / fees / operational /
 * warranty fields stay at 0 today — they need:
 *   - Cost: ProductCost line-item attribution (orders.lines × ProductCost option pick)
 *   - Tax: per-Store Taxes rate × revenue
 *   - Fees: FeesConfiguration gateway/checkout/shipping per order
 *   - Operational: per-period OperationalCost spread
 *   - Warranty: per-period WarrantyReserve rate × revenue
 *
 * The aggregations to land them all exist as separate use cases /
 * repos already; the cross-aggregate join lands in a follow-up that
 * introduces an Analytics application service to keep this controller
 * decoupled from the source BCs.
 *
 * `profitAmountCents = revenue - (cost + tax + fees + marketing +
 * operational + warranty)`. `marginPercent = profit / revenue * 100`.
 */
@injectable()
export class GetProfitMarginReport extends Handler<typeof GetProfitMarginReportInputSchema, typeof GetProfitMarginReportOutputSchema> {
	readonly name = 'get_profit_margin_report' as const
	readonly inputSchema = GetProfitMarginReportInputSchema
	readonly outputSchema = GetProfitMarginReportOutputSchema

	constructor(private readonly db: DrizzleClient) {
		super()
	}

	protected async handle(input: this['input'], tx?: DrizzleClient): Promise<this['output']> {
		const dbc = tx ?? this.db
		const fromDate = input.from
		const toDate = input.to
		const unit = bucketUnit(input.frequency as AnalyticsFrequency)
		const unitLiteral = sql.raw(`'${unit}'`)

		const revenueBucket = sql<string>`to_char(date_trunc(${unitLiteral}, ${orders.externalCreatedAt}), 'YYYY-MM-DD')`
		const marketingBucket = sql<string>`to_char(date_trunc(${unitLiteral}, ${adSpends.bucketStart}), 'YYYY-MM-DD')`

		const [revenueRows, marketingRows] = await Promise.all([
			dbc
				.select({
					period: revenueBucket,
					total: sql<string>`sum(${orders.totalCents})`,
				})
				.from(orders)
				.where(and(inArray(orders.storeId, input.storeIds), gte(orders.externalCreatedAt, fromDate), lte(orders.externalCreatedAt, toDate)))
				.groupBy(revenueBucket),
			dbc
				.select({
					period: marketingBucket,
					total: sql<string>`sum(${adSpends.amountCents})`,
				})
				.from(adSpends)
				.where(and(inArray(adSpends.storeId, input.storeIds), gte(adSpends.bucketStart, fromDate), lte(adSpends.bucketStart, toDate)))
				.groupBy(marketingBucket),
		])

		const byPeriod = new Map<string, PeriodRow>()
		const ensure = (period: string): PeriodRow => {
			if (!byPeriod.has(period)) {
				byPeriod.set(period, {
					periodStart: period,
					revenueAmountCents: 0,
					costAmountCents: 0,
					taxAmountCents: 0,
					feesAmountCents: 0,
					marketingAmountCents: 0,
					operationalAmountCents: 0,
					warrantyAmountCents: 0,
					profitAmountCents: 0,
					marginPercent: 0,
				})
			}
			return byPeriod.get(period)!
		}

		for (const r of revenueRows as Array<{ period: string; total: string | null }>) {
			ensure(r.period).revenueAmountCents = Number(r.total ?? 0)
		}
		for (const r of marketingRows as Array<{ period: string; total: string | null }>) {
			ensure(r.period).marketingAmountCents = Number(r.total ?? 0)
		}

		for (const p of byPeriod.values()) {
			const deductions =
				p.costAmountCents + p.taxAmountCents + p.feesAmountCents + p.marketingAmountCents + p.operationalAmountCents + p.warrantyAmountCents
			p.profitAmountCents = p.revenueAmountCents - deductions
			p.marginPercent = p.revenueAmountCents > 0 ? (p.profitAmountCents / p.revenueAmountCents) * 100 : 0
		}

		const periods = [...byPeriod.values()].sort((a, b) => (a.periodStart < b.periodStart ? -1 : 1))
		return {
			reportingCurrency: CurrencyCode.USD,
			periods,
		}
	}
}

const BUCKET_UNIT: Record<AnalyticsFrequency, string> = {
	[AnalyticsFrequency.HOURLY]: 'hour',
	[AnalyticsFrequency.DAILY]: 'day',
	[AnalyticsFrequency.WEEKLY]: 'week',
	[AnalyticsFrequency.MONTHLY]: 'month',
	[AnalyticsFrequency.YEARLY]: 'year',
}

function bucketUnit(freq: AnalyticsFrequency): string {
	return BUCKET_UNIT[freq]
}

