import { describe, expect, it } from 'bun:test'
import { OperationalCostRecurrency } from '@bk-dash/contracts-typescript/wire/enums'
import { countOccurrencesInRange, isRecurring, occurrenceAt, occurrenceWindow } from './recurrence'

const d = (iso: string) => new Date(iso)
const FAR_FUTURE = d('2100-01-01T00:00:00.000Z')

describe('recurrence math', () => {
	describe('countOccurrencesInRange', () => {
		it('counts MONTHLY occurrences within the series bounds', () => {
			// Jan15..Jun15 inclusive = 6
			const n = countOccurrencesInRange(
				d('2026-01-15T00:00:00.000Z'),
				d('2026-06-15T00:00:00.000Z'),
				OperationalCostRecurrency.MONTHLY,
				d('2026-01-01T00:00:00.000Z'),
				d('2027-01-01T00:00:00.000Z'),
			)
			expect(n).toBe(6)
		})

		it('counts DAILY occurrences capped by effectiveEnd', () => {
			const n = countOccurrencesInRange(
				d('2026-01-01T00:00:00.000Z'),
				d('2026-01-10T00:00:00.000Z'),
				OperationalCostRecurrency.DAILY,
				d('2026-01-01T00:00:00.000Z'),
				d('2027-01-01T00:00:00.000Z'),
			)
			expect(n).toBe(10) // Jan 1..10 inclusive
		})

		it('counts WEEKLY occurrences', () => {
			const n = countOccurrencesInRange(
				d('2026-01-01T00:00:00.000Z'),
				FAR_FUTURE,
				OperationalCostRecurrency.WEEKLY,
				d('2026-01-01T00:00:00.000Z'),
				d('2026-02-01T00:00:00.000Z'),
			)
			expect(n).toBe(5) // Jan 1, 8, 15, 22, 29
		})

		it('treats `to` as exclusive (half-open window)', () => {
			const n = countOccurrencesInRange(
				d('2026-01-01T00:00:00.000Z'),
				FAR_FUTURE,
				OperationalCostRecurrency.WEEKLY,
				d('2026-01-01T00:00:00.000Z'),
				d('2026-01-15T00:00:00.000Z'),
			)
			expect(n).toBe(2) // Jan 1, Jan 8 — Jan 15 == to is excluded
		})

		it('respects a `from` later than the series start', () => {
			const n = countOccurrencesInRange(
				d('2026-01-01T00:00:00.000Z'),
				FAR_FUTURE,
				OperationalCostRecurrency.MONTHLY,
				d('2026-04-01T00:00:00.000Z'),
				d('2026-07-01T00:00:00.000Z'),
			)
			expect(n).toBe(3) // Apr 1, May 1, Jun 1
		})

		it('ONCE / NONE collapse to a single occurrence at startDate', () => {
			const inRange = countOccurrencesInRange(
				d('2026-03-01T00:00:00.000Z'),
				FAR_FUTURE,
				OperationalCostRecurrency.ONCE,
				d('2026-01-01T00:00:00.000Z'),
				d('2027-01-01T00:00:00.000Z'),
			)
			expect(inRange).toBe(1)

			const outOfRange = countOccurrencesInRange(
				d('2026-03-01T00:00:00.000Z'),
				FAR_FUTURE,
				OperationalCostRecurrency.NONE,
				d('2026-04-01T00:00:00.000Z'),
				d('2027-01-01T00:00:00.000Z'),
			)
			expect(outOfRange).toBe(0)
		})
	})

	describe('occurrenceWindow', () => {
		it('materializes only the requested page while reporting the full total', () => {
			const { total, dates } = occurrenceWindow(
				d('2026-01-01T00:00:00.000Z'),
				d('2026-01-30T00:00:00.000Z'),
				OperationalCostRecurrency.DAILY,
				d('2026-01-01T00:00:00.000Z'),
				d('2027-01-01T00:00:00.000Z'),
				2,
				10,
			)
			expect(total).toBe(30)
			expect(dates).toHaveLength(10) // page 2 → days 11..20
			expect(dates[0]).toEqual(d('2026-01-11T00:00:00.000Z'))
			expect(dates[9]).toEqual(d('2026-01-20T00:00:00.000Z'))
		})
	})

	describe('occurrenceAt', () => {
		it('clamps month-end overflow (Jan 31 + 1 month → Feb 28 in a non-leap year)', () => {
			const o = occurrenceAt(d('2026-01-31T00:00:00.000Z'), OperationalCostRecurrency.MONTHLY, 1)
			expect(o).toEqual(d('2026-02-28T00:00:00.000Z'))
		})

		it('returns null past the only occurrence for ONCE/NONE', () => {
			expect(occurrenceAt(d('2026-01-01T00:00:00.000Z'), OperationalCostRecurrency.ONCE, 1)).toBeNull()
		})
	})

	describe('isRecurring', () => {
		it('is false for ONCE / NONE and true otherwise', () => {
			expect(isRecurring(OperationalCostRecurrency.ONCE)).toBe(false)
			expect(isRecurring(OperationalCostRecurrency.NONE)).toBe(false)
			expect(isRecurring(OperationalCostRecurrency.MONTHLY)).toBe(true)
			expect(isRecurring(OperationalCostRecurrency.DAILY)).toBe(true)
		})
	})
})

